package worldgen

import (
	"bufio"
	"math"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
)

// Generated by docs/worldgen/ReferenceProbe.java against the supplied JAR.
func TestXoroshiroMatchesVanilla1211(t *testing.T) {
	f, err := os.Open(filepath.Join("..", "..", "docs", "worldgen", "xoroshiro_1.21.1.txt"))
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	longs := make(map[int64]*Xoroshiro)
	bounds := make(map[int64]*Xoroshiro)
	fractions := make(map[int64]*Xoroshiro)
	scanner := bufio.NewScanner(f)
	checks := 0
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) < 3 {
			t.Fatalf("invalid fixture row %q", scanner.Text())
		}
		seed, err := strconv.ParseInt(fields[1], 10, 64)
		if err != nil {
			t.Fatal(err)
		}
		value, err := strconv.ParseUint(fields[len(fields)-1], 10, 64)
		if err != nil {
			t.Fatal(err)
		}
		var got uint64
		switch fields[0] {
		case "long":
			if longs[seed] == nil {
				longs[seed] = NewXoroshiro(seed)
			}
			got = longs[seed].NextLong()
		case "bound":
			if bounds[seed] == nil {
				bounds[seed] = NewXoroshiro(seed)
			}
			bound, err := strconv.ParseInt(fields[2], 10, 32)
			if err != nil {
				t.Fatal(err)
			}
			got = uint64(bounds[seed].NextIntBound(int32(bound)))
		case "float":
			if fractions[seed] == nil {
				fractions[seed] = NewXoroshiro(seed)
			}
			got = uint64(math.Float32bits(fractions[seed].NextFloat()))
		case "double":
			if fractions[seed] == nil {
				fractions[seed] = NewXoroshiro(seed)
			}
			got = math.Float64bits(fractions[seed].NextDouble())
		case "position":
			got = NewXoroshiro(seed).ForkPositional().At(-17, 68, 33).NextLong()
		case "hash":
			got = NewXoroshiro(seed).ForkPositional().FromHashOf("minecraft:terrain").NextLong()
		default:
			t.Fatalf("unknown fixture row %q", scanner.Text())
		}
		if got != value {
			t.Fatalf("%s: got %d, vanilla %d", scanner.Text(), got, value)
		}
		checks++
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	if checks != 56 {
		t.Fatalf("got %d reference checks, want 56", checks)
	}
}
